//! The G-SP memo prototype (`benches/spike/memo.rs`) checked against cold evaluation: after every kind of edit
//! the spike measures, the memoised value equals the cold one, with `ew-memo`'s oracle on at every depth.
//! Non-timing; class S only (the L/XL fixtures are generated by the spike run).

#[allow(dead_code)]
#[path = "../benches/spike/memo.rs"]
mod memo;

use std::num::NonZeroU32;

use ew_api::{Session, SessionOptions};
use ew_commands::commands::{Connect, EndpointParam, MoveReps};
use ew_commands::testkit::seeded_ids;
use ew_derive::{DepKey, PageLocalNets, PotentialPartition, Q};
use ew_memo::{Durability, Oracle, Store};
use ew_model::Model;
use ew_testkit::synth::{self, SizeClass};
use ew_units::Pt2;

use memo::{Memo, ModelDb, durability_of_keys, evaluate, minimal_deps, store_at};

fn session(model: &Model) -> Session {
    Session::new(
        model.clone(),
        SessionOptions {
            ids: Some(seeded_ids(1)),
            ..Default::default()
        },
    )
}

/// Advances `store` past the session's last commit and returns the database of the new snapshot.
fn advance(store: &mut Store<ModelDb>, session: &mut Session) -> ModelDb {
    let keys: Vec<_> = session
        .drain_changes()
        .into_iter()
        .flat_map(|c| c.touched_keys)
        .collect();
    let db = ModelDb::new(&session.world().model);
    store.advance(db.rev(), durability_of_keys(&keys));
    db
}

fn assert_partition_matches_cold(store: &mut Store<ModelDb>, db: &ModelDb) {
    let memoised = store.get::<Memo<PotentialPartition>>(db, &()).expect("no cycle");
    let cold = Q::new(db.model()).get::<PotentialPartition>(());
    assert_eq!(**memoised, *cold, "memoised potential_partition equals cold");
    assert!(store.take_mismatches().is_empty(), "the oracle found no mismatch");
}

#[test]
fn minimal_deps_drop_rows_of_tables_read_whole() {
    let g = synth::project(SizeClass::S, 1);
    let model = Model::from_records(g.project, g.records, g.lib).expect("valid model");
    let (_, reads) = evaluate::<PotentialPartition>(&model, &());
    let deps = minimal_deps(&reads);
    assert!(!deps.is_empty() && deps.len() <= reads.len());
    let whole: Vec<_> = deps
        .iter()
        .filter_map(|d| match d {
            DepKey::Table(k) => Some(*k),
            _ => None,
        })
        .collect();
    assert!(
        deps.iter()
            .all(|d| !matches!(d, DepKey::Row((k, _)) if whole.contains(k)))
    );
    let mut sorted = deps.clone();
    sorted.sort();
    sorted.dedup();
    assert_eq!(sorted, deps, "sorted and unique");
}

#[test]
fn stamps_of_the_db_are_the_stamps_q_observed() {
    let g = synth::project(SizeClass::S, 1);
    let model = Model::from_records(g.project, g.records, g.lib).expect("valid model");
    let (_, reads) = evaluate::<PageLocalNets>(&model, &g.handles.pages[0]);
    let db = ModelDb::new(&model);
    for (dep, observed) in reads {
        assert_eq!(ew_memo::Db::changed_at(&db, &dep).0, observed.0, "{dep:?}");
    }
}

#[test]
fn memoised_connectivity_equals_cold_after_move_wire_and_hit() {
    let g = synth::project(SizeClass::S, 1);
    let handles = g.handles.clone();
    let model = Model::from_records(g.project, g.records, g.lib).expect("valid model");
    let db0 = ModelDb::new(&model);
    let mut warm = store_at(&db0);
    warm.set_oracle(Oracle::Every);
    assert_partition_matches_cold(&mut warm, &db0);
    for page in &handles.pages {
        warm.get::<Memo<PageLocalNets>>(&db0, page).expect("no cycle");
    }
    // A second read at the same revision is a hit.
    assert_partition_matches_cold(&mut warm, &db0);
    assert!(warm.commit_stats().family("potential_partition").hits >= 1);

    // A move of a load representation.
    let mut fork = warm.fork();
    let mut s = session(&model);
    let delta = Pt2::new(handles.grid.at(6).unwrap(), handles.grid.at(3).unwrap());
    s.execute(&MoveReps {
        reps: vec![handles.load_reps[0]],
        delta,
        page: None,
    })
    .expect("move accepted");
    let db1 = advance(&mut fork, &mut s);
    assert_partition_matches_cold(&mut fork, &db1);
    for page in &handles.pages {
        let m = fork.get::<Memo<PageLocalNets>>(&db1, page).expect("no cycle");
        assert_eq!(**m, *Q::new(db1.model()).get::<PageLocalNets>(*page));
    }
    assert!(fork.take_mismatches().is_empty());

    // A new wire.
    let mut fork = warm.fork();
    fork.set_oracle(Oracle::OneIn(NonZeroU32::new(1).unwrap()));
    let mut s = session(&model);
    let p = (0..handles.pages.len())
        .find(|p| handles.free_cps[*p].len() >= 2)
        .expect("a page with two free CPs");
    let (a, b) = (handles.free_cps[p][0], handles.free_cps[p][1]);
    s.execute(&Connect {
        a: EndpointParam::Cp {
            function: a.0,
            idx: a.1,
        },
        b: EndpointParam::Cp {
            function: b.0,
            idx: b.1,
        },
        page: Some(handles.pages[p]),
        route: Vec::new(),
        kind: Default::default(),
    })
    .expect("wire accepted");
    let db2 = advance(&mut fork, &mut s);
    assert_partition_matches_cold(&mut fork, &db2);
    let nets = fork
        .get::<Memo<PageLocalNets>>(&db2, &handles.pages[p])
        .expect("no cycle");
    assert_eq!(
        **nets,
        *Q::new(db2.model()).get::<PageLocalNets>(handles.pages[p])
    );
    assert!(fork.take_mismatches().is_empty());
}

#[test]
fn durability_of_commits() {
    use ew_schema::Kind;
    let id = ew_ids::Id::<()>::from_uuid(ew_ids::Uuid::from_u128(1));
    assert_eq!(durability_of_keys(&[]), Durability::Drawing);
    assert_eq!(durability_of_keys(&[(Kind::Connection, id)]), Durability::Drawing);
    assert_eq!(
        durability_of_keys(&[(Kind::Connection, id), (Kind::Project, id)]),
        Durability::Settings
    );
    assert_eq!(
        durability_of_keys(&[(Kind::Symbol, id), (Kind::Project, id)]),
        Durability::Library
    );
    assert_eq!(memo::durability_of(&DepKey::Project), Durability::Settings);
    assert_eq!(
        memo::durability_of(&DepKey::Table(Kind::Fndef)),
        Durability::Library
    );
}
